// Fictional browser contract only. Database/permission behavior is tested separately.
import type { LiveSchedule } from '../../app/scheduler-workspace-model';
import { scheduleEligibility, scheduleDates } from '../../app/scheduler-workspace-model';
import { normalizeScheduleTime } from '../../app/schedule-time';
import type { SavedScheduleSafety } from '../../app/schedule-safety-store';
import { validateScheduleSafetyRules } from '../../app/schedule-safety';

export function fixtureScheduleAction(data: LiveSchedule & { scheduleSafety: SavedScheduleSafety }, body: Record<string, unknown>) {
  const action=String(body.action), id=String(body.id||''), slot=data.slots.find(s=>s.id===body.slotId);
  const mine=['saveAvailability','deleteAvailability','submitClaim','submitTrade','respondTrade'];
  if(!data.viewer.isAdmin && !mine.includes(action)) throw Error('Administrator access is required.');
  const employeeId=String(body.memberId||body.employeeId||data.viewer.employeeId||'');
  if(!data.viewer.isAdmin && employeeId!==data.viewer.employeeId) throw Error('This fixture member cannot edit another member.');
  const member=data.employees.find(e=>e.id===employeeId);
  const assign=(slotId:string,employeeId:string|null)=>{const s=data.slots.find(s=>s.id===slotId);if(!s)throw Error('Position not found.');if(employeeId){const problem=scheduleEligibility(data,employeeId,s);if(problem)throw Error(problem);}Object.assign(s,{employeeId,employeeName:data.employees.find(e=>e.id===employeeId)?.name||'',status:employeeId?'filled':'open'});};
  if(action==='saveAvailability') {
    const dates=Array.isArray(body.dates)?[...new Set(body.dates.map(String))]:[];
    if(!dates.length||dates.length>93)throw Error('Choose 1–93 dates.');
    for(const date of dates) { scheduleDates(date,date); const old=data.availability.find(a=>a.employeeId===employeeId&&a.availabilityDate===date);const values={id:old?.id||`availability-${employeeId}-${date}`,employeeId,employeeName:member?.name||'',availabilityDate:date,status:body.status==='unavailable'?'unavailable' as const:'available' as const,allDay:body.allDay?1:0,startTime:normalizeScheduleTime(String(body.startTime))||'06:00',endTime:normalizeScheduleTime(String(body.endTime))||'18:00',note:String(body.note||''),updatedAt:new Date().toISOString()};if(old)Object.assign(old,values);else data.availability.push(values); }
  } else if(action==='deleteAvailability') data.availability=data.availability.filter(a=>a.employeeId!==employeeId||a.availabilityDate!==body.date);
  else if(action==='submitClaim') {if(!slot||slot.status!=='open')throw Error('That position is no longer open.');if(data.claims.some(c=>c.slotId===slot.id&&c.employeeId===employeeId&&c.status==='pending'))throw Error('Request already exists.');data.claims.push({id:`claim-${data.claims.length}`,slotId:slot.id,employeeId,employeeName:member?.name||'',role:slot.role,entryDate:slot.entryDate,status:'pending',note:String(body.note||''),createdAt:data.today});}
  else if(action==='submitTrade') {if(!slot)throw Error('Choose a saved position.');data.trades.push({id:`trade-${data.trades.length}`,slotId:slot.id,returnSlotId:String(body.returnSlotId||'')||null,role:slot.role,entryDate:slot.entryDate,fromEmployeeId:employeeId,fromEmployeeName:member?.name||'',targetEmployeeId:String(body.targetEmployeeId||'')||null,acceptedByEmployeeId:null,status:'awaiting_acceptance',note:String(body.note||''),createdAt:data.today});}
  else if(action==='respondTrade') {const t=data.trades.find(t=>t.id===id);if(!t)throw Error('Trade not found.');if(body.decision==='decline')t.status='denied';else Object.assign(t,{acceptedByEmployeeId:employeeId,status:'awaiting_acceptance'});}
  else if(action==='reviewClaim') {const c=data.claims.find(c=>c.id===id);if(!c)throw Error('Request not found.');if(body.decision==='approved')assign(c.slotId,c.employeeId);c.status=String(body.decision);}
  else if(action==='reviewTrade') {const t=data.trades.find(t=>t.id===id);if(!t)throw Error('Trade not found.');if(body.decision==='approved'){if(!t.acceptedByEmployeeId)throw Error('A member must accept first.');assign(t.slotId,t.acceptedByEmployeeId);if(t.returnSlotId)assign(t.returnSlotId,t.fromEmployeeId);}t.status=String(body.decision);}
  else if(action==='assignSlot'||action==='clearSlot') {if(!slot)throw Error('Choose a position.');assign(slot.id,action==='clearSlot'?null:employeeId);}
  else if(action==='saveShiftType') {const shiftId=id||`shift-${data.shiftTypes.length}`;const old=data.shiftTypes.find(s=>s.id===shiftId);const values={id:shiftId,name:String(body.name),startTime:normalizeScheduleTime(String(body.startTime))||'06:00',endTime:normalizeScheduleTime(String(body.endTime))||'18:00',anchorDate:String(body.anchorDate),repeatEveryDays:Number(body.repeatEveryDays),color:String(body.color),active:1,sortOrder:0};if(old)Object.assign(old,values);else data.shiftTypes.push(values);data.shiftTypeRoles=data.shiftTypeRoles.filter(r=>r.shiftTypeId!==shiftId);if(Array.isArray(body.roleRequirements))for(const r of body.roleRequirements)data.shiftTypeRoles.push({id:`${shiftId}-${r.role}`,shiftTypeId:shiftId,role:r.role,count:r.count});}
  else if(action==='deactivateShiftType') {const s=data.shiftTypes.find(s=>s.id===id);if(s)s.active=0;}
  else if(action==='createEntry') {const type=data.shiftTypes.find(s=>s.id===body.shiftTypeId);if(!type)throw Error('Choose a shift.');const e={id:`entry-${data.entries.length}`,entryDate:String(body.date),shiftTypeId:type.id};data.entries.push(e);for(const r of data.shiftTypeRoles.filter(r=>r.shiftTypeId===type.id))for(let n=0;n<r.count;n++)data.slots.push({id:`slot-${data.slots.length}`,entryId:e.id,entryDate:e.entryDate,shiftTypeId:type.id,role:r.role,employeeId:null,status:'open',startTime:type.startTime,endTime:type.endTime,sortOrder:n,isExtra:0,hasTimeOverride:0});}
  else if(action==='deleteEntry') {data.slots=data.slots.filter(s=>s.entryId!==body.entryId);data.entries=data.entries.filter(e=>e.id!==body.entryId);}
  else if(action==='addDaySlot') {const existingEntry=data.entries.find(e=>e.id===body.entryId);const type=data.shiftTypes.find(s=>s.id===(body.shiftTypeId||existingEntry?.shiftTypeId));if(!type)throw Error('Choose a shift.');let e=existingEntry||data.entries.find(e=>e.entryDate===body.date&&e.shiftTypeId===type.id);if(!e){e={id:`entry-${data.entries.length}`,entryDate:String(body.date),shiftTypeId:type.id};data.entries.push(e);}data.slots.push({id:`extra-${data.slots.length}`,entryId:e.id,entryDate:e.entryDate,shiftTypeId:type.id,role:String(body.role),employeeId:body.employeeId?employeeId:null,employeeName:body.employeeId?member?.name:'',status:body.employeeId?'filled':'open',startTime:normalizeScheduleTime(String(body.startTime))||type.startTime,endTime:normalizeScheduleTime(String(body.endTime))||type.endTime,sortOrder:99,isExtra:1,hasTimeOverride:1,staffingReason:String(body.staffingReason||'')});}
  else if(action==='updateDaySlot'||action==='updateDaySlotTime') {if(!slot)throw Error('Choose a position.');const type=data.shiftTypes.find(t=>t.id===slot.shiftTypeId)!;Object.assign(slot,{startTime:body.reset?type.startTime:normalizeScheduleTime(String(body.startTime)),endTime:body.reset?type.endTime:normalizeScheduleTime(String(body.endTime)),hasTimeOverride:body.reset?0:1});if(action==='updateDaySlot'){slot.role=String(body.role);assign(slot.id,body.employeeId?employeeId:null);}}
  else if(action==='deleteDaySlot') data.slots=data.slots.filter(s=>s.id!==body.slotId);
  else if(action==='saveStandingAssignment') data.standingAssignments.push({id:`standing-${data.standingAssignments.length}`,employeeId,employeeName:member?.name||'',shiftTypeId:String(body.shiftTypeId),role:String(body.role),active:1});
  else if(action==='removeStandingAssignment') data.standingAssignments=data.standingAssignments.filter(s=>s.id!==id);
  else if(action==='saveEmployeeScheduler') {if(member)Object.assign(member,{notifyEmail:body.notifyEmail?1:0,notifyText:body.notifyText?1:0});}
  else if(action==='saveRequestDeadline') {data.requestDeadlines=(data.requestDeadlines||[]).filter(d=>d.id!==body.slotId);if(body.deadline)data.requestDeadlines.push({id:String(body.slotId),deadline:String(body.deadline)});}
  else if(action==='saveReminderRule') {const r=data.reminderRules.find(r=>r.id===id);if(r)Object.assign(r,{enabled:body.enabled?1:0,pushEnabled:body.pushEnabled?1:0,offsets:JSON.stringify(body.offsets)});}
  else if(action==='saveScheduleSafety') {if(body.revision!==data.scheduleSafety.revision)throw Error('Saved rules changed. Refresh first.');data.scheduleSafety={revision:'fixture-'+Date.now(),updatedAt:new Date().toISOString(),rules:validateScheduleSafetyRules(body.rules)};return {ok:true,saved:data.scheduleSafety};}
  else throw Error('Unsupported fixture action: '+action);
  return {ok:true,note:'Saved in isolated fictional records only.'};
}
